#include <stdio.h>
void conv(double y,double u,double v){
  float fy=y,fu=u,fv=v;
  float fr=fy+1.140f*fv, fg=fy-0.395f*fu-0.581f*fv, fb=fy+2.032f*fu;
  float fmn=fr<fg?fr:fg; if(fb<fmn)fmn=fb;
  float fmx=fr>fg?fr:fg; if(fb>fmx)fmx=fb;
  float fd=fmx-fmn, fl=(fmn+fmx)/2, fh, fs;
  if(fd==0){fh=0;fs=0;}else{
    fs=fd/(1-(2*fl-1<0?1-2*fl:2*fl-1));
    if(fmx==fr)fh=60*(fg-fb)/fd; else if(fmx==fg)fh=60*(fb-fr)/fd+120; else fh=60*(fr-fg)/fd+240;
    if(fh<0)fh+=360;
  }
  printf("f32: %.6g %.6g %.6g %.6g %.6g %.6g\n",fr,fg,fb,fh,fs,fl);
  double r=y+1.140*v, g=y-0.395*u-0.581*v, b=y+2.032*u;
  double mn=r<g?r:g; if(b<mn)mn=b;
  double mx=r>g?r:g; if(b>mx)mx=b;
  double d=mx-mn, l=(mn+mx)/2, h, s;
  if(d==0){h=0;s=0;}else{
    s=d/(1-(2*l-1<0?1-2*l:2*l-1));
    if(mx==r)h=60*(g-b)/d; else if(mx==g)h=60*(b-r)/d+120; else h=60*(r-g)/d+240;
    if(h<0)h+=360;
  }
  printf("f64: %.6g %.6g %.6g %.6g %.6g %.6g\n",r,g,b,h,s,l);
}
int main(){
  conv(0.123456,0.234567,0.345678);
  conv(0.987654,-0.456789,0.111111);
  conv(0.333333,0.777777,-0.222222);
  conv(0.7654321,0.13579,-0.246813);
  conv(2.5,1.5,-1.5);
  conv(-0.5,0.9,0.4);
  conv(0.5,0.2,0.3);
  return 0;
}
EOF
