#include <stdio.h>
void conv(double y,double u,double v){
  float fy=y,fu=u,fv=v;
  float r=fy+1.140*fv, g=fy-0.395*fu-0.581*fv, b=fy+2.032*fu;
  float mn=r<g?r:g; if(b<mn)mn=b;
  float mx=r>g?r:g; if(b>mx)mx=b;
  float d=mx-mn, l=(mn+mx)/2, h, s;
  if(d==0){h=0;s=0;}else{
    s=d/(1-(2*l-1<0?1-2*l:2*l-1));
    if(mx==r)h=60*(g-b)/d; else if(mx==g)h=60*(b-r)/d+120; else h=60*(r-g)/d+240;
    if(h<0)h+=360;
  }
  printf("v1 (f32 members, dbl literals, store each): %.6g %.6g %.6g %.6g %.6g %.6g\n",r,g,b,h,s,l);
}
void conv2(double y,double u,double v){
  // all float arithmetic with float literals, but s via formula s=d/(1-fabs(2*l-1)) with l possibly kept
  float fy=y,fu=u,fv=v;
  float r=fy+1.140f*fv, g=fy-0.395f*fu-0.581f*fv, b=fy+2.032f*fu;
  float mn=r<g?r:g; if(b<mn)mn=b;
  float mx=r>g?r:g; if(b>mx)mx=b;
  float d=mx-mn, l=(mn+mx)/2, h, s;
  if(d==0){h=0;s=0;}else{
    if(l<0.5f) s=d/(mx+mn); else s=d/(2-mx-mn);
    if(mx==r)h=60*(g-b)/d; else if(mx==g)h=60*(b-r)/d+120; else h=60*(r-g)/d+240;
    if(h<0)h+=360;
  }
  printf("v2 (alt s formula): %.6g %.6g %.6g %.6g %.6g %.6g\n",r,g,b,h,s,l);
}
void conv3(double y,double u,double v){
  // float members, hue via fmod like berendeanicolae: h=60*fmod((g-b)/d,6) etc stored to float
  float fy=y,fu=u,fv=v;
  float r=fy+1.140*fv, g=fy-0.395*fu-0.581*fv, b=fy+2.032*fu;
  double dr=r,dg=g,db=b;
  double mn=dr<dg?dr:dg; if(db<mn)mn=db;
  double mx=dr>dg?dr:dg; if(db>mx)mx=db;
  double d=mx-mn; float l=(mn+mx)/2, h, s;
  if(d==0){h=0;s=0;}else{
    s=d/(1-fabs(2*l-1));
    if(mx==dr)h=60*fmod((dg-db)/d,6);
    else if(mx==dg)h=60*((db-dr)/d+2);
    else h=60*((dr-dg)/d+4);
    if(h<0)h+=360;
  }
  printf("v3 (float rgb, double hsl calc, fmod hue): %.6g %.6g %.6g %.6g %.6g %.6g\n",r,g,b,h,s,l);
}
int main(){
  double cases[][3]={{0.123456,0.234567,0.345678},{0.987654,-0.456789,0.111111},{0.333333,0.777777,-0.222222},{0.7654321,0.13579,-0.246813},{2.5,1.5,-1.5},{-0.5,0.9,0.4},{0.5,0.2,0.3}};
  for(int i=0;i<7;i++){conv(cases[i][0],cases[i][1],cases[i][2]);conv2(cases[i][0],cases[i][1],cases[i][2]);conv3(cases[i][0],cases[i][1],cases[i][2]);}
  return 0;
}
EOF
