  float r=y+1.140f*v, g=y-0.395f*u-0.581f*v, b=y+2.032f*u;
  float mn=r<g?r:g; if(b<mn)mn=b;
  float mx=r>g?r:g; if(b>mx)mx=b;
  float d=mx-mn, l=(mn+mx)/2;
  float h1=0; double h2=0, h3=0; float h4=0; double h5=0;
  if(d!=0){
    // h1: all float
    if(mx==r)h1=60*(g-b)/d; else if(mx==g)h1=60*(b-r)/d+120; else h1=60*(r-g)/d+240;
    if(h1<0)h1+=360;
    // h2: double arithmetic from float values, same formula
    if(mx==r)h2=60.0*(g-b)/d; else if(mx==g)h2=60.0*(b-r)/d+120; else h2=60.0*(r-g)/d+240;
    if(h2<0)h2+=360;
    // h3: fmod double style (berendeanicolae-like)
