/// Emulate C++ std::stof / strtof prefix parsing.
pub fn stof(s: &str) -> f32 {
    let s = s.trim_start_matches(|c: char| {
        matches!(c, ' ' | '\t' | '\n' | '\u{0b}' | '\u{0c}' | '\r')
    });
    // Longest prefix (on char boundaries) that Rust's f32 parser accepts.
    let mut end = s.len();
    while end > 0 {
        if s.is_char_boundary(end) {
            if let Ok(v) = s[..end].parse::<f32>() {
                return v;
            }
        }
        end -= 1;
    }
    panic!("stof: no conversion could be performed");
}

/// Reproduce glibc printf("%.6g", (double)x) exactly.
pub fn g6(x: f32) -> String {
    let d = x as f64;
    if d.is_nan() {
        return if d.is_sign_negative() {
            "-nan".to_string()
        } else {
            "nan".to_string()
        };
    }
    if d.is_infinite() {
        return if d.is_sign_negative() {
            "-inf".to_string()
        } else {
            "inf".to_string()
        };
    }
    if d == 0.0 {
        return if d.is_sign_negative() {
            "-0".to_string()
        } else {
            "0".to_string()
        };
    }
    let neg = d.is_sign_negative();
    let (digits, x_exp) = exact_digits(d);
    let (digits, x_exp) = round_sig(digits, x_exp, 6);
    let body = present(&digits, x_exp);
    if neg {
        format!("-{}", body)
    } else {
        body
    }
}

fn mul_small(d: &mut Vec<u8>, k: u8) {
    // little-endian decimal digits, multiply by small k
    let mut carry: u32 = 0;
    for dig in d.iter_mut() {
        let v = (*dig as u32) * (k as u32) + carry;
        *dig = (v % 10) as u8;
        carry = v / 10;
    }
    while carry > 0 {
        d.push((carry % 10) as u8);
        carry /= 10;
    }
}

/// Exact decimal expansion of |x| (nonzero finite f64).
/// Returns (digits most-significant-first, X) with |x| = D.DDDD... x 10^X.
fn exact_digits(x: f64) -> (Vec<u8>, i32) {
    let bits = x.abs().to_bits();
    let raw_e = ((bits >> 52) & 0x7ff) as i64;
    let frac = bits & 0x000f_ffff_ffff_ffff;
    let (m, e2): (u64, i64) = if raw_e == 0 {
        (frac, -1074)
    } else {
        (frac | (1u64 << 52), raw_e - 1075)
    };
    let mut d: Vec<u8> = Vec::new(); // little-endian
    let mut mm = m;
    while mm > 0 {
        d.push((mm % 10) as u8);
        mm /= 10;
    }
    let x_exp: i32;
    if e2 >= 0 {
        for _ in 0..e2 {
            mul_small(&mut d, 2);
        }
        x_exp = d.len() as i32 - 1;
    } else {
        let k = (-e2) as usize;
        for _ in 0..k {
            mul_small(&mut d, 5);
        }
        x_exp = d.len() as i32 - 1 - k as i32;
    }
    d.reverse(); // most-significant first
    (d, x_exp)
}

/// Round exact digit string to `p` significant digits, round-half-to-even
/// using the exact remainder. Returns (digits, X); handles carry-out.
fn round_sig(digits: Vec<u8>, x_exp: i32, p: usize) -> (Vec<u8>, i32) {
    if digits.len() <= p {
        return (digits, x_exp);
    }
    let mut kept: Vec<u8> = digits[..p].to_vec();
    let first_dropped = digits[p];
    let rest_nonzero = digits[p + 1..].iter().any(|&d| d != 0);
    let round_up = if first_dropped > 5 {
        true
    } else if first_dropped < 5 {
        false
    } else if rest_nonzero {
        true
    } else {
        // exact tie: keep last kept digit even
        kept[p - 1] % 2 == 1
    };
    let mut x_exp = x_exp;
    if round_up {
        let mut i = p;
        loop {
            if i == 0 {
                kept.insert(0, 1);
                kept.pop();
                x_exp += 1;
                break;
            }
            i -= 1;
            if kept[i] == 9 {
                kept[i] = 0;
            } else {
                kept[i] += 1;
                break;
            }
        }
    }
    // strip trailing zeros
    while kept.len() > 1 && *kept.last().unwrap() == 0 {
        kept.pop();
    }
    (kept, x_exp)
}

/// C %g presentation with precision P=6 (trailing zeros stripped).
fn present(digits: &[u8], x_exp: i32) -> String {
    let s: String = digits.iter().map(|d| (b'0' + d) as char).collect();
    if x_exp < -4 || x_exp >= 6 {
        // scientific
        let mut out = String::new();
        out.push_str(&s[..1]);
        if s.len() > 1 {
            let frac = s[1..].trim_end_matches('0');
            if !frac.is_empty() {
                out.push('.');
                out.push_str(frac);
            }
        }
        let sign = if x_exp < 0 { '-' } else { '+' };
        out.push('e');
        out.push(sign);
        let ae = x_exp.abs();
        if ae < 10 {
            out.push('0');
        }
        out.push_str(&ae.to_string());
        out
    } else if x_exp >= 0 {
        let int_len = x_exp as usize + 1;
        if s.len() >= int_len {
            let frac = s[int_len..].trim_end_matches('0');
            if frac.is_empty() {
                s[..int_len].to_string()
            } else {
                format!("{}.{}", &s[..int_len], frac)
            }
        } else {
            let mut out = s;
            for _ in 0..(int_len - out.len()) {
                out.push('0');
            }
            out
        }
    } else {
        // -4 <= X <= -1: 0.00...ddd
        let zeros = (-x_exp - 1) as usize;
        let mut out = String::from("0.");
        for _ in 0..zeros {
            out.push('0');
        }
        let frac_full = format!("{}{}", "0".repeat(zeros), s);
        let _ = frac_full;
        out.push_str(s.trim_end_matches('0'));
        // s starts with a nonzero digit, so fractional part never empties
        out
    }
}

