# Domain D verification: huge magnitudes
REF=/workspace/dataset/test17_executable
RUST=/output/test17
mism=0
total=0
declare -a REPORT

run_case() {
    total=$((total+1))
    a_out=$("$REF" "$@" 2>/dev/null); a_st=$?
    b_out=$("$RUST" "$@" 2>/dev/null); b_st=$?
    if [ "$a_out" != "$b_out" ] || [ "$a_st" != "$b_st" ]; then
        mism=$((mism+1))
        if [ ${#REPORT[@]} -lt 10 ]; then
            REPORT+=("ARGS: $* | REF($a_st): $a_out | RUST($b_st): $b_out")
        fi
    fi
}

# 1) Random log-uniform in [1e2, 1e38], both signs, %.6e
for i in $(seq 1 380); do
    read y u v < <(awk -v s=$i 'BEGIN{
        srand(s);
        r="";
        for(k=0;k<3;k++){
            e=2+rand()*36;
            m=1+rand()*9;
            sgn=(rand()<0.5)?-1:1;
            printf "%s%.6e", (k?" ":""), sgn*m*(10^e);
        }
        printf "\n";
    }')
    run_case "$y" "$u" "$v"
done

