#!/bin/bash
# Generate crafted cases for Domain E: exact decimal ties and %g boundary exponents.
# Emits one case per line: "y u v"

awk 'BEGIN{
  # small dyadic sets
  n1=split("0.5 0.25 0.125 0.0625 0.84375 0.15625 3.078125", d1, " ");
  n2=split("0.03125 0.09375 0.1875 0.3125 0.4375 0.6875 0.9375 1.25 1.875 2.5", d2, " ");
  # probes near %g fixed/scientific boundaries and exponent edges
  n3=split("0.0001 0.00001 0.0000999999 0.0001000001 100000 999999.5 9999999 0.000009999999 99999.95 1000000.5", d3, " ");
  # nested loops over small dyadic sets
  for(i=1;i<=n1;i++) for(j=1;j<=n1;j++) for(k=1;k<=n1;k++)
    printf "%s %s %s\n", d1[i], d1[j], d1[k];            # 343
  for(i=1;i<=n2;i++) for(j=1;j<=n1;j++)
    printf "%s %s %s\n", d2[i], d1[j], d1[(i+j)%n1+1];   # 70
  # boundary probes paired with dyadic values
