REF=/workspace/dataset/test17_executable; RUST=/output/test17
mism=0; exitonly=0; total=0
for i in $(seq 1 400); do
    mapfile -t args < <(awk -v s=$((i*7919+13)) 'BEGIN{
        srand(s);
        efmt = (rand() < 0.5) ? "%.8e" : "%.6e";
        for (k=0;k<3;k++){
            e = -38 + rand()*36; m = 1 + rand()*9; v = m * (10 ^ e);
            if (rand() < 0.5) v = -v; printf efmt "\n", v;
        }
    }')
    total=$((total+1))
    a=$("$REF" "${args[@]}" 2>/dev/null); ra=$?
    b=$("$RUST" "${args[@]}" 2>/dev/null); rb=$?
    if [ "$a" != "$b" ]; then mism=$((mism+1)); elif [ "$ra" != "$rb" ]; then exitonly=$((exitonly+1)); fi
done
# subnormal + underflow sections
for i in $(seq 1 50); do
    read -r a1 a2 a3 <<<"$(awk -v s=$((i*31337+3)) 'BEGIN{srand(s);split("1e-39 1e-45 5e-40 1e-40 1.4e-45 -1e-39 -1e-45 1e-42",v," ");for(k=0;k<3;k++)printf "%s ",v[int(rand()*8)+1];printf "\n"}')"
